// spec: specs/premium-store.md (раздел 3.4)
// seed: tests/seed.free.spec.ts
import { test, expect, type Page } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/free-r13.json'), colorScheme: 'dark' });

async function checkUpgradeButton(page: Page, route: '/boosts' | '/super-likes') {
  await page.goto(route);
  const upgrade = page.getByRole('button', { name: 'לשדרוג — מעבר לחנות' });
  await expect(upgrade).toBeVisible();

  // Кнопка под плитками цен: top >= низ плиток, top <= верх «יש לך».
  const tilesBottom = Math.max(
    ...(await Promise.all((await page.getByRole('radio').all()).map(async (t) => {
      const b = await t.boundingBox();
      return b ? b.y + b.height : 0;
    }))),
  );
  const upgradeBox = (await upgrade.boundingBox())!;
  const haveBox = (await page.getByText(/^יש לך$/).boundingBox())!;
  expect(upgradeBox.y, 'кнопка ниже плиток цен').toBeGreaterThanOrEqual(tilesBottom - 1);
  expect(upgradeBox.y, 'кнопка выше «יש לך»').toBeLessThanOrEqual(haveBox.y);

  await upgrade.click();
  await expect(page).toHaveURL(/\/paywall/);
  await expect(page.getByText('חנות', { exact: true }).first()).toBeVisible();
  await expect(page.getByText('שדכנית אישית', { exact: true })).toBeVisible();
  await expect(page.getByRole('button', { name: /^פרימיום/ })).toBeVisible();
  await expect(page.getByRole('button', { name: /^בוסטים/ })).toBeVisible();
  await expect(page.getByRole('button', { name: /^סופר לייק · / })).toBeVisible();
  await expect(page.getByRole('button', { name: /^מתנות · / })).toBeVisible();
  await expect(page.getByText('Magnet Premium', { exact: true })).toBeVisible();

  await page.getByRole('button', { name: 'חזרה' }).click();
  await expect(page).toHaveURL(new RegExp(route));
}

test.describe('Раунд 13: «בוסטים» и «סופר לייק» (#4ef651)', () => {
  test('«לשדרוג — מעבר לחנות» открывает полный «חנות» @iphone @prod-safe', async ({ page }) => {
    const purchaseRequests: string[] = [];
    page.on('request', (r) => {
      if (/purchase|payment|checkout/i.test(r.url())) purchaseRequests.push(r.url());
    });

    // 1. `/boosts`; найти «לשדרוג — מעבר לחנות»; нажать.
    // 2. «назад»; то же на `/super-likes`.
    await checkUpgradeButton(page, '/boosts');
    await checkUpgradeButton(page, '/super-likes');

    expect(purchaseRequests, 'запросов покупки нет').toEqual([]);
  });
});
